begin;
create extension if not exists pgtap with schema extensions;
set local search_path=public,extensions;
select plan(35);
select has_table('public','projects','Projects exist');
select has_table('public','project_revisions','Revision snapshots exist');
select is((select relrowsecurity from pg_class where oid='public.projects'::regclass),true,'Projects have RLS');
select is((select relrowsecurity from pg_class where oid='public.project_revisions'::regclass),true,'Revisions have RLS');
insert into auth.users(id,email) values
 ('11111111-1111-4111-8111-111111111111','project-alice@example.test'),
 ('22222222-2222-4222-8222-222222222222','project-bob@example.test');
set local role anon;
select throws_ok($$select public.create_idea_project('{}','test-create-key-0001')$$,'42501',null,'Anonymous RPC is denied');
set local role authenticated;
select set_config('request.jwt.claims','{"sub":"11111111-1111-4111-8111-111111111111","role":"authenticated"}',true);
select set_config('test.created',public.create_idea_project('{"title":"First idea","brief":"Original explanation"}','test-create-key-0001')::text,true);
select ok((current_setting('test.created')::jsonb->>'id') is not null,'Create returns its committed project');
select is((current_setting('test.created')::jsonb->>'revision')::integer,1,'Initial revision is one');
select is(public.create_idea_project('{"title":"First idea","brief":"Original explanation"}','test-create-key-0001'),current_setting('test.created')::jsonb,'Create replay returns original acknowledgement');
select throws_ok($$select public.create_idea_project('{"title":"Different"}','test-create-key-0001')$$,'P0001','IDEMPOTENCY_CONFLICT','Changed command cannot reuse key');
select is((select count(*) from public.projects),1::bigint,'Create retry produces one project');
select throws_ok($$insert into public.projects(owner_id,title) values(auth.uid(),'Bypass')$$,'42501',null,'Direct insert denied');
select throws_ok($$update public.projects set title='Bypass'$$,'42501',null,'Direct update denied');
select throws_ok('delete from public.projects','42501',null,'Direct deletion denied');
select throws_ok($$insert into public.project_revisions(owner_id,project_id,revision) values(auth.uid(),gen_random_uuid(),1)$$,'42501',null,'Direct snapshot insertion denied');
select throws_ok($$select public.create_idea_project('{"owner_id":"22222222-2222-4222-8222-222222222222"}','test-create-key-0002')$$,'P0001','VALIDATION_FAILED','Client cannot choose owner');
select throws_ok($$select public.save_idea_project((current_setting('test.created')::jsonb->>'id')::uuid,'{"expectedRevision":"1","title":"Invalid"}','test-save-key-0001')$$,'P0001','VALIDATION_FAILED','Version must be numeric');
select throws_ok('select * from private.project_commands','42501',null,'Idempotency records stay private');
select set_config('test.saved',public.save_idea_project((current_setting('test.created')::jsonb->>'id')::uuid,'{"expectedRevision":1,"title":"Renamed idea","brief":"Revised explanation"}','test-save-key-0001')::text,true);
select is((current_setting('test.saved')::jsonb->>'revision')::integer,2,'Save advances version');
select is((select title from public.project_revisions where revision=1),'First idea','Old title is preserved');
select is((select brief from public.project_revisions where revision=1),'Original explanation','Old idea is preserved');
select is(public.save_idea_project((current_setting('test.created')::jsonb->>'id')::uuid,'{"expectedRevision":1,"title":"Renamed idea","brief":"Revised explanation"}','test-save-key-0001'),current_setting('test.saved')::jsonb,'Lost save response can be replayed before CAS');
select is((select count(*) from public.project_revisions),2::bigint,'Retry does not duplicate revision');
select throws_ok($$select public.save_idea_project((current_setting('test.created')::jsonb->>'id')::uuid,'{"expectedRevision":1,"title":"Stale"}','test-save-key-0002')$$,'P0001','REVISION_CONFLICT','Stale save is rejected');
select is((select count(*) from public.project_revisions),2::bigint,'Failed command rolls back completely');
select set_config('request.jwt.claims','{"sub":"22222222-2222-4222-8222-222222222222","role":"authenticated"}',true);
select throws_ok($$select public.get_idea_project((current_setting('test.created')::jsonb->>'id')::uuid)$$,'P0001','RESOURCE_NOT_FOUND','Bob cannot open Alice project');
select is(jsonb_array_length(public.list_idea_projects()),0,'Bob library is empty');
select is((select count(*) from public.projects),0::bigint,'Direct project reads are isolated');
select is((select count(*) from public.project_revisions),0::bigint,'Direct snapshot reads are isolated');
select throws_ok($$select public.save_idea_project((current_setting('test.created')::jsonb->>'id')::uuid,'{"expectedRevision":2,"title":"Stolen"}','test-save-key-0003')$$,'P0001','RESOURCE_NOT_FOUND','Bob cannot update Alice project');
reset role;
update public.profiles set deletion_status='pending' where owner_id='22222222-2222-4222-8222-222222222222';
set local role authenticated;
select throws_ok($$select public.create_idea_project('{}','test-create-key-0003')$$,'P0001','ACCOUNT_UNAVAILABLE','Inactive identity cannot author');
reset role;
update public.projects set deleted_at=now() where id=(current_setting('test.created')::jsonb->>'id')::uuid;
set local role authenticated;
select set_config('request.jwt.claims','{"sub":"11111111-1111-4111-8111-111111111111","role":"authenticated"}',true);
select throws_ok($$select public.get_idea_project((current_setting('test.created')::jsonb->>'id')::uuid)$$,'P0001','RESOURCE_NOT_FOUND','Tombstoned project is unavailable');
select is((select count(*) from public.project_revisions),0::bigint,'Tombstoned history is hidden');
reset role;
select throws_ok($$insert into public.project_revisions(owner_id,project_id,revision,title,brief,reference_text,target_duration_ms,audience_level,tone,settings,content_hash) values('22222222-2222-4222-8222-222222222222',(current_setting('test.created')::jsonb->>'id')::uuid,3,'Wrong owner','','',60000,'beginner','clear','{}',repeat('a',64))$$,'23503',null,'Composite FK enforces owner agreement');
set constraints projects_head_revision_fk immediate;
select throws_ok($$update public.projects set edit_version=99 where id=(current_setting('test.created')::jsonb->>'id')::uuid$$,'23503',null,'Head cannot reference absent snapshot');
set local role authenticated;
select throws_ok($$update public.project_revisions set brief='Overwrite history'$$,'42501',null,'Snapshot update denied to clients');
select * from finish();
rollback;
